// Local-only aggregation of CSVs generated by demo-concurrency-test.mjs. No network.
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { configuredUrl, save } from './demo-concurrency-test.mjs';

export function parseCsv(text) {
  const records = []; let row = [], cell = '', quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '"') {
      if (quoted && text[i+1] === '"') { cell += '"'; i++; }
      else quoted = !quoted;
    } else if (!quoted && (c === ',' || c === '\n')) {
      row.push(cell); cell = '';
      if (c === '\n') { records.push(row); row = []; }
    } else cell += c;
  }
  if (quoted) throw new Error('INVALID_CSV');
  if (cell || row.length) { row.push(cell); records.push(row); }
  const keys = records.shift() || [];
  return records.map(r => Object.fromEntries(keys.map((k,i) => {
    const v = r[i] ?? '';
    return [k, v === 'true' ? true : v === 'false' ? false : v !== '' && /^\d+(\.\d+)?$/.test(v) ? Number(v) : v];
  })));
}

export async function combine(names) {
  if (!names.length || names.some(n => !/^load-[a-zA-Z0-9-]+$/.test(n)) || new Set(names).size !== names.length) throw new Error('Provide unique load-* batch directory names only');
  const root = fileURLToPath(new URL('../test-results/', import.meta.url));
  const state = { batchId: `combined-${new Date().toISOString().replace(/[-:.]/g,'')}`, phase: '合併已完成階段',
    createdAt: new Date().toISOString(), apiUrl: await configuredUrl(), preflight: '來源報告已驗證，這次合併不發送任何 HTTP',
    runners: [], http: [], stopped: null };
  for (const name of names) {
    const folder = resolve(root,name);
    const report = await readFile(resolve(folder,'report.md'),'utf8');
    if (!report.includes(state.apiUrl) || !report.includes('Demo 預檢：PASS:')) throw new Error('Source preflight missing or API mismatch');
    const reason = report.match(/停止原因：([^\n]+)/)?.[1];
    if (reason && !reason.startsWith('無')) state.stopped = reason;
    state.runners.push(...parseCsv(await readFile(resolve(folder,'runners.csv'),'utf8')));
    state.http.push(...parseCsv(await readFile(resolve(folder,'http.csv'),'utf8')));
  }
  const ids = state.runners.map(r=>r.requestId);
  if (new Set(ids).size !== ids.length) throw new Error('Duplicate runner request IDs across batches');
  await save(state,resolve(root,state.batchId));
  console.log(resolve(root,state.batchId));
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  combine(process.argv.slice(2)).catch(e=>{console.error(e.message);process.exitCode=1;});
}
